  static String? getReferenceForPoint(String pointVerification) {
    final meta = DispositionsConstructivesRegistry.getMetadata(pointVerification);
    if (meta != null) {
      return NormativeReferenceCleaner.clean(meta.referenceNormative);
    }
    final ref = _normativeReferences[pointVerification];
    if (ref == null) return null;
    return NormativeReferenceCleaner.clean(ref);
  }

  /// Vérifie si un point a une référence normative
  static bool hasReference(String pointVerification) {
    if (DispositionsConstructivesRegistry.getMetadata(pointVerification) != null) {
      return true;
    }
    return _normativeReferences.containsKey(pointVerification);
  }
}
